package sidecarflight

import (
	"encoding/hex"
	"math"
	"testing"

	"github.com/matrixorigin/matrixone/pkg/common/mpool"
	"github.com/matrixorigin/matrixone/pkg/container/types"
	"github.com/matrixorigin/matrixone/pkg/container/vector"
	planpb "github.com/matrixorigin/matrixone/pkg/pb/plan"
	"github.com/stretchr/testify/require"
)

// Generated by Arrow C++ 25.0, the same native Arrow major used by the
// sidecar. Keeping the bytes in the Go test makes the production package
// independent of both a Go Arrow package and a native Arrow installation.
const fixtureSchemaHex = ""

const fixtureHeaderHex = ""

const fixtureBodyHex = ""

func TestArrowIPCDecodesNegotiatedTPCHTypes(t *testing.T) {
	schemaWire := mustHex(t, fixtureSchemaHex)
	header := mustHex(t, fixtureHeaderHex)
	body := mustHex(t, fixtureBodyHex)
	typesOut := []planpb.Type{
		{Id: int32(types.T_bool)}, {Id: int32(types.T_int8)}, {Id: int32(types.T_int16)},
		{Id: int32(types.T_int32)}, {Id: int32(types.T_int64)}, {Id: int32(types.T_float32)},
		{Id: int32(types.T_float64)}, {Id: int32(types.T_varchar)},
		{Id: int32(types.T_decimal64), Width: 18, Scale: 2},
		{Id: int32(types.T_decimal128), Width: 38, Scale: 4},
		{Id: int32(types.T_date)}, {Id: int32(types.T_uint32)},
	}
	headings := []string{"b", "i8", "i16", "i32", "i64", "f32", "f64", "s", "d64", "d128", "date", "u32_transport"}
	schema, err := ParseSchema(schemaWire, typesOut, headings)
	require.NoError(t, err)
	require.NoError(t, schema.validateStreamSchema(schemaWire))

	mp := mpool.MustNewZero()
	bat, err := schema.decodeRecordBatch(header, body, 1<<20, mp)
	require.NoError(t, err)
	require.Equal(t, 2, bat.RowCount())
	for _, vec := range bat.Vecs {
		require.False(t, vec.IsNull(0))
		require.True(t, vec.IsNull(1))
	}
	require.True(t, vector.GetFixedAtNoTypeCheck[bool](bat.Vecs[0], 0))
	require.Equal(t, int8(-8), vector.GetFixedAtNoTypeCheck[int8](bat.Vecs[1], 0))
	require.Equal(t, int16(-16), vector.GetFixedAtNoTypeCheck[int16](bat.Vecs[2], 0))
	require.Equal(t, int32(-32), vector.GetFixedAtNoTypeCheck[int32](bat.Vecs[3], 0))
	require.Equal(t, int64(-64), vector.GetFixedAtNoTypeCheck[int64](bat.Vecs[4], 0))
	require.Equal(t, float32(1.25), vector.GetFixedAtNoTypeCheck[float32](bat.Vecs[5], 0))
	require.Equal(t, 2.5, vector.GetFixedAtNoTypeCheck[float64](bat.Vecs[6], 0))
	require.Equal(t, "tpch", bat.Vecs[7].GetStringAt(0))
	require.Equal(t, types.Decimal64(^uint64(12344)), vector.GetFixedAtNoTypeCheck[types.Decimal64](bat.Vecs[8], 0))
	require.Equal(t, types.Decimal128{B0_63: 7, B64_127: 1}, vector.GetFixedAtNoTypeCheck[types.Decimal128](bat.Vecs[9], 0))
	require.Equal(t, types.DaysFromUnixEpochToDate(1), vector.GetFixedAtNoTypeCheck[types.Date](bat.Vecs[10], 0))
	require.Equal(t, uint32(42), vector.GetFixedAtNoTypeCheck[uint32](bat.Vecs[11], 0))
	bat.Clean(mp)
	require.Equal(t, int64(0), mp.CurrNB())
}

func TestArrowIPCRejectsMalformedAndMismatchedData(t *testing.T) {
	require.Equal(t, int64(math.MaxInt64/8+1), bitmapBytes(math.MaxInt64))
	schemaWire := mustHex(t, fixtureSchemaHex)
	typesOut, headings := fixtureOutputShape()
	for length := 0; length < len(schemaWire); length += 31 {
		_, err := ParseSchema(schemaWire[:length], typesOut, headings)
		require.Error(t, err)
	}
	_, err := ParseSchema(schemaWire, []planpb.Type{{Id: int32(types.T_int64)}}, []string{"wrong"})
	require.ErrorContains(t, err, "expects 1")

	schema, err := ParseSchema(schemaWire, typesOut, headings)
	require.NoError(t, err)
	mp := mpool.MustNewZero()
	body := mustHex(t, fixtureBodyHex)
	header := mustHex(t, fixtureHeaderHex)
	for length := 0; length < len(header); length += 17 {
		_, err = schema.decodeRecordBatch(header[:length], body, 1<<20, mp)
		require.Error(t, err)
	}
	_, err = schema.decodeRecordBatch(mustHex(t, fixtureHeaderHex), body, 1, mp)
	require.ErrorContains(t, err, "decoded-memory budget")

	required := *schema
	required.fields = append([]arrowField(nil), schema.fields...)
	required.fields[0].nullable = false
	_, err = required.decodeRecordBatch(mustHex(t, fixtureHeaderHex), body, 1<<20, mp)
	require.ErrorContains(t, err, "required field contains nulls")

	_, err = schema.decodeRecordBatch(mustHex(t, fixtureHeaderHex), body[:len(body)-1], 1<<20, mp)
	require.ErrorContains(t, err, "body length mismatch")
	require.Equal(t, int64(0), mp.CurrNB())
}

func mustHex(t *testing.T, value string) []byte {
	t.Helper()
	decoded, err := hex.DecodeString(value)
	require.NoError(t, err)
	return decoded
}
